local _, WFJ = ...
WFJ.Data.add("book", {
  ["f52b46daa9db6023"] = { "Giorno 6:\n\nDi primo mattino, Thorsen ha parlato a lungo con il sergente Yohwa. Ho dovuto fingere di dormire ancora, quindi non ho potuto avvicinarmi abbastanza da sentire. Ma immagino che abbiano parlato dell'escursione di Thorsen.\n\nA pranzo l'ho osservato attentamente, e ho notato che Yohwa faceva lo stesso. Più tardi, Doren ha convocato Thorsen. Quei tre condividono un segreto. Doren e Yohwa devono sapere che Thorsen incontra i tuoi agenti.\n\nFa la spia per i ribelli.", "." },
  ["f5620e7ef2ed8df5"] = { "Capitolo 2 - Brinarossa e ⟦Tower Point=Torre Granguardia⟧\n\nUna volta abbattuto il primo strato, resterà scoperto il secondo strato del 'carciofo'. Distruggere le torri dei Lupi Bianchi vicine alle prime linee paralizzerà i legionari e le pattuglie che brulicano sul fianco posteriore.\n\nLe torri sono pesantemente fortificate, e ognuna ospita uno dei comandanti scelti di Drek'Thar. Vanno uccisi. Questo accelererà lo smantellamento delle difese dei Lupi Bianchi.", "." },
  ["f575944328868a6f"] = { "Col passare del tempo, Ner'zhul comprese quale sorte attendeva i clan per mano della Legione Infuocata, e lo sciamano degli orchi cominciò a sfidare Kil'jaeden. Il demone, irritato da Ner'zhul, si rivolse all'apprendista dello sciamano, Gul'dan, che era molto più corruttibile di Ner'zhul.", "." },
  ["f57636df8d22b9fc"] = { "Mentre la battaglia infuriava sui campi in fiamme di Kalimdor, si verificò un terribile colpo di scena. I dettagli dell'evento sono andati perduti nel tempo, ma è noto che Neltharion, l'Aspetto dei Draghi della Terra, impazzì durante uno scontro decisivo contro la Legione Infuocata. Cominciò a spaccarsi mentre fiamme e furia eruttavano dalla sua pelle scura. Ribattezzatosi Alamorte, il drago in fiamme si rivoltò contro i suoi simili e scacciò i cinque stormi dal campo di battaglia.", "." },
  ["f5b826c5a3ab3d29"] = { "Quando le nebbie dell'alba svanirono e l'Età della Memoria avanzò, il semidio Cenarius prese la sua strada per i campi del mondo. Gli Shu'halo (i tauren) furono addolorati dalla sua partenza e dimenticarono gran parte del druidismo che aveva loro insegnato. Con il passare delle generazioni dimenticarono come parlare con gli alberi e con le creature selvagge della terra. Gli oscuri sussurri dalle profondità del mondo tornarono a salire fino alle loro orecchie.", "." },
})
